contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that once Initialized() has been called, SetMinSum cannot succeed anymore.
    // Parameters: a value to attempt to set as MinSum after initialization.
    function run(uint newMin) public payable {
        // 1) Before calling Initialized, SetMinSum should be allowed (contract is fresh), so call it once to ensure normal behavior.
        // We don't check its effect; we just ensure it doesn't revert here so that Initialized transition is meaningful.
        bool preReverted;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            preReverted = true;
        } else {
            preReverted = false;
        }

        // If the first SetMinSum call reverted unexpectedly, we still proceed to call Initialized to reach the asserted property.
        // 2) Call Initialized to flip the flag.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // 3) Now attempt to call SetMinSum again; it SHOULD revert because intitalized was set.
        bool postReverted;
        c.SetMinSum(newMin); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            postReverted = true;
        } else {
            postReverted = false;
        }

        // General rule: after Initialized() has been called, SetMinSum must revert for any input.
        // We allow the pre-Initialized call to have either reverted or not (some implementations might restrict it),
        // but require that the post-Initialized attempt does revert.
        assert(postReverted);
    }

    receive() external payable {}
}

